-- KUP SI APKU - schema v1
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,first_name VARCHAR(100) NOT NULL,last_name VARCHAR(100) NOT NULL,phone VARCHAR(40),street VARCHAR(190),city VARCHAR(100),postal_code VARCHAR(20),country_code CHAR(2) NOT NULL DEFAULT 'CZ',company_name VARCHAR(190),ico VARCHAR(20),dic VARCHAR(30),role ENUM('customer','affiliate','admin') NOT NULL DEFAULT 'customer',status ENUM('pending','active','blocked','deleted') NOT NULL DEFAULT 'pending',email_verified_at DATETIME,last_login_at DATETIME,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_users_role_status(role,status),KEY idx_users_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS auth_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,ip_hash CHAR(64),user_agent VARCHAR(500),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,last_used_at DATETIME,revoked_at DATETIME,KEY idx_session_user_active(user_id,revoked_at,expires_at),KEY idx_session_expiry(expires_at),CONSTRAINT fk_session_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS email_verification_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,used_at DATETIME,KEY idx_verify_user(user_id,used_at,expires_at),KEY idx_verify_expiry(expires_at),CONSTRAINT fk_verify_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS password_reset_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,used_at DATETIME,KEY idx_reset_user(user_id,used_at,expires_at),KEY idx_reset_expiry(expires_at),CONSTRAINT fk_reset_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS referral_codes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,code VARCHAR(50) NOT NULL UNIQUE,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME,KEY idx_ref_user(user_id),KEY idx_ref_active(is_active),CONSTRAINT fk_ref_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS referral_clicks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,referral_code_id BIGINT UNSIGNED NOT NULL,session_token CHAR(64) NOT NULL,landing_page VARCHAR(255),referrer_url VARCHAR(500),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_click_ref_created(referral_code_id,created_at),KEY idx_click_session(session_token),CONSTRAINT fk_click_ref FOREIGN KEY(referral_code_id) REFERENCES referral_codes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(190) NOT NULL,price_minor BIGINT UNSIGNED NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'CZK',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_product_active(is_active)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_number VARCHAR(40) NOT NULL UNIQUE,user_id BIGINT UNSIGNED,referral_code_id BIGINT UNSIGNED,customer_email VARCHAR(190) NOT NULL,customer_first_name VARCHAR(100) NOT NULL,customer_last_name VARCHAR(100) NOT NULL,customer_phone VARCHAR(40),billing_street VARCHAR(190),billing_city VARCHAR(100),billing_postal_code VARCHAR(20),billing_country_code CHAR(2) NOT NULL DEFAULT 'CZ',company_name VARCHAR(190),ico VARCHAR(20),dic VARCHAR(30),subtotal_minor BIGINT UNSIGNED NOT NULL,discount_minor BIGINT UNSIGNED NOT NULL DEFAULT 0,total_minor BIGINT UNSIGNED NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'CZK',status ENUM('pending','awaiting_payment','paid','cancelled','refunded') NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,paid_at DATETIME,cancelled_at DATETIME,KEY idx_order_user_created(user_id,created_at),KEY idx_order_ref(referral_code_id),KEY idx_order_status(status,created_at),KEY idx_order_email(customer_email),CONSTRAINT fk_order_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_order_ref FOREIGN KEY(referral_code_id) REFERENCES referral_codes(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED,product_code VARCHAR(50) NOT NULL,product_name VARCHAR(190) NOT NULL,quantity SMALLINT UNSIGNED NOT NULL DEFAULT 1,unit_price_minor BIGINT UNSIGNED NOT NULL,total_minor BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_item_order(order_id),KEY idx_item_product(product_id),CONSTRAINT fk_item_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,CONSTRAINT fk_item_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,method ENUM('bank_qr','gopay','manual') NOT NULL,amount_minor BIGINT UNSIGNED NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'CZK',variable_symbol VARCHAR(20) UNIQUE,provider_reference VARCHAR(190) UNIQUE,qr_payload TEXT,status ENUM('pending','processing','paid','failed','cancelled','refunded') NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,paid_at DATETIME,KEY idx_payment_order(order_id),KEY idx_payment_status(status,created_at),CONSTRAINT fk_payment_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS commissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,affiliate_user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL UNIQUE,base_amount_minor BIGINT UNSIGNED NOT NULL,commission_rate DECIMAL(5,2) NOT NULL,commission_minor BIGINT UNSIGNED NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'CZK',status ENUM('pending','approved','payable','paid','cancelled') NOT NULL DEFAULT 'pending',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,approved_at DATETIME,payable_at DATETIME,paid_at DATETIME,KEY idx_comm_aff_status(affiliate_user_id,status),KEY idx_comm_created(created_at),CONSTRAINT fk_comm_aff FOREIGN KEY(affiliate_user_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_comm_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
